+/**
+ * Safely parse a version expression string without using eval or new Function().
+ * Supported formats: ">=58", ">58", "<=58", "<58", "==58", "=58", "58"
+ * 
+ * @param expression - The version expression string to parse
+ * @returns An object containing the operator and version number, or null if invalid
+ */
+export function parseVersionExpression(expression: string): { operator: string; version: number } | null {
+  if (!expression || typeof expression !== "string") {
+    return null;
+  }
+
+  // Match operator and version number
+  // Operators: >=, >, <=, <, ==, =
+  const match = expression.match(/^(>=|>|<=|==|=|<)(\d+)$/);
+  
+  if (!match) {
+    return null;
+  }
+
+  const operator = match[1];
+  const version = parseInt(match[2], 10);
+
+  if (isNaN(version)) {
+    return null;
+  }
+
+  return { operator, version };
+}

